# Resilient HTTP helper for DNS/connectivity issues
import socket
import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

def requests_session_with_retries(retries=3, backoff=0.5, status_forcelist=(500, 502, 503, 504)):
    """Create requests session with retry logic for transient failures"""
    s = requests.Session()
    retry = Retry(
        total=retries,
        backoff_factor=backoff,
        status_forcelist=status_forcelist,
        allowed_methods=["GET", "POST"]
    )
    adapter = HTTPAdapter(max_retries=retry)
    s.mount("http://", adapter)
    s.mount("https://", adapter)
    return s

def resolve_hostname_or_log(hostname, timeout=2.0):
    """Attempt DNS resolution with logging"""
    try:
        ip = socket.gethostbyname(hostname)
        logger.debug(f"✅ Resolved {hostname} → {ip}")
        return ip
    except Exception as e:
        logger.warning(f"⚠️  DNS lookup failed for {hostname}: {e}")
        return None

