    def _ensure_account_log_file(self) -> None:
        """Ensure per-account log file naming convention.

        Default: logs/trader-<account>.log unless TRADER_LOG_FILE env override is set.
        """
        if os.getenv("TRADER_LOG_FILE"):
            return
        desired = f"logs/trader-{self.account_id}.log"
        desired_abs = os.path.abspath(desired)
        for handler in list(logger.handlers):
            if isinstance(handler, logging.FileHandler):
                try:
                    if os.path.abspath(handler.baseFilename) == desired_abs:
                        return
                except Exception:
                    pass
        # Replace existing file handlers with the account-specific file
        for handler in list(logger.handlers):
            if isinstance(handler, logging.FileHandler):
                logger.removeHandler(handler)
                try:
                    handler.close()
                except Exception:
                    pass
        file_handler = logging.FileHandler(desired)
        file_handler.setLevel(logging.INFO)
        file_handler.setFormatter(logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s'))
        logger.addHandler(file_handler)

    def _account_label(self) -> str:
        """Human-friendly account label for Telegram messages."""
        aid = str(self.account_id or "").strip().lower()
        if aid == "primary":
            return "Wajid"
        if aid == "asjad":
            return "Asjad"
        return str(self.account_id or "UNKNOWN").upper()

    @staticmethod
    def _display_symbol(sym: str) -> str:
        """Display-only symbol formatter (keeps internal symbol unchanged).

        Policy:
        - Remove trailing 'USDT' suffix for display.
        - Strip Binance contract prefixes like '1000'/'10000' (e.g., 1000SHIB -> SHIB).
        """
        try:
            s = str(sym or "").upper().strip()
        except Exception:
            return "UNKNOWN"
        base = s
        if base.endswith("USDT") and len(base) > 4:
            base = base[:-4]

        # Handle 1000-prefixed perp symbols used by Binance.
        for prefix in ("10000", "1000"):
            if base.startswith(prefix) and len(base) > len(prefix):
                base = base[len(prefix) :]
                break

        return base or "UNKNOWN"

    @staticmethod
    def _coin_icon_for_base(base_sym: str) -> str:
        """Best-effort coin icon mapping (unicode only)."""
        s = str(base_sym or "").upper().strip()
        icons = {
            "BTC": "₿",
            "ETH": "Ξ",
            "SOL": "◎",
            "XRP": "✕",
            "LTC": "Ł",
            "DOGE": "Ð",
            "LINK": "🔗",
            "UNI": "🦄",
            "PEPE": "🐸",
            "SHIB": "🐶",
            "BONK": "🐕",
            "FLOKI": "🐺",
        }
        return icons.get(s, "🪙")

    def _coin_icon(self, sym: str) -> str:
        base = self._display_symbol(sym)
        return self._coin_icon_for_base(base)

    def _crypto_icons_manifest_path(self) -> str:
        try:
            repo_root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
            return os.path.join(repo_root, "assets", "crypto-icons", "manifest.json")
        except Exception:
            return ""

    def _load_crypto_icons_manifest(self) -> dict:
        cache = getattr(self, "_crypto_icons_manifest_cache", None)
        if isinstance(cache, dict) and cache:
            return cache
        manifest_path = self._crypto_icons_manifest_path()
        if not manifest_path or not os.path.exists(manifest_path):
            setattr(self, "_crypto_icons_manifest_cache", {})
            return {}
        try:
            with open(manifest_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                data = {}
            setattr(self, "_crypto_icons_manifest_cache", data)
            return data
        except Exception:
            setattr(self, "_crypto_icons_manifest_cache", {})
            return {}

    def _crypto_icon_png_path_for_symbol(self, sym: str) -> Optional[str]:
        try:
            if not bool(getattr(self.config, "TELEGRAM_ENABLE_ICON_MEDIA", False)):
                return None
            if not bool(getattr(self.config, "TELEGRAM_TRADE_ICON_MEDIA", True)):
                return None

            base = self._display_symbol(sym)
            manifest = self._load_crypto_icons_manifest()
            icons = (manifest or {}).get("icons") or {}
            entry = icons.get(str(base).upper()) or {}
            rel_png = (entry.get("path_png") or "").strip()
            rel_any = (entry.get("path") or "").strip()

            repo_root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
            candidates = []
            if rel_png:
                candidates.append(os.path.join(repo_root, rel_png))
            if rel_any and not rel_any.lower().endswith(".svg"):
                candidates.append(os.path.join(repo_root, rel_any))
            # Last resort: generic.png
            candidates.append(os.path.join(repo_root, "assets", "crypto-icons", "GENERIC.png"))
            candidates.append(os.path.join(repo_root, "assets", "crypto-icons", "generic.png"))

            for p in candidates:
                if p and os.path.exists(p) and os.path.getsize(p) > 0:
                    return p
            return None
        except Exception:
            return None

    def _portfolio_icon_media_paths(self, display_items_sorted: List[Dict[str, Any]], max_icons: int) -> List[str]:
        try:
            if not bool(getattr(self.config, "TELEGRAM_ENABLE_ICON_MEDIA", False)):
                return []
            if not bool(getattr(self.config, "TELEGRAM_PORTFOLIO_ICON_MEDIA", True)):
                return []
            max_icons = int(max_icons or 0)
            if max_icons <= 0:
                return []

            seen = set()
            out: List[str] = []
            for item in (display_items_sorted or []):
                sym = item.get("symbol")
                disp = self._display_symbol(sym)
                b = str(disp).upper().strip()
                if not b or b in seen:
                    continue
                seen.add(b)
                p = self._crypto_icon_png_path_for_symbol(sym)
                if p and p not in out:
                    out.append(p)
                if len(out) >= max_icons:
                    break
            return out
        except Exception:
            return []

    def _fmt_symbol(self, sym: str) -> str:
        base = self._display_symbol(sym)
        return f"{self._coin_icon_for_base(base)} {base}".strip()

    def _fmt_symbol_html(self, sym: str) -> str:
        base = self._display_symbol(sym)
        return f"{self._coin_icon_for_base(base)} <b>{base}</b>".strip()

    def _add_blocked_trade_to_batch(self, symbol: str, action: str, reason: str, detail: str, conf_pct: float, tf: str):
        """Add a blocked trade to the batch for periodic summary alerts."""
        self._blocked_trades_batch.append({
            'symbol': symbol,
            'action': action,
            'reason': reason,
            'detail': detail,
            'conf_pct': conf_pct,
            'tf': tf,
            'ts': time.time()
        })
        # Keep batch bounded to prevent memory issues
        if len(self._blocked_trades_batch) > 500:
            self._blocked_trades_batch = self._blocked_trades_batch[-250:]

    def _send_blocked_trades_summary(self):
        """Send a summary of blocked trades if any exist, then clear batch."""
        if not self._blocked_trades_batch or not self.telegram:
            return
        
        try:
            acct = self._account_label()
            batch = self._blocked_trades_batch.copy()
            self._blocked_trades_batch.clear()
            
            # Group by reason
            by_reason: Dict[str, List[Dict]] = {}
            for item in batch:
                r = item['reason']
                if r not in by_reason:
                    by_reason[r] = []
                by_reason[r].append(item)
            
            # Build summary message
            lines = [
                f"📊 <b>BLOCKED TRADES SUMMARY</b>",
                f"👤 <b>{acct}</b> | Last {self._blocked_summary_interval // 60} min",
                f"⚠️ Total blocked: <b>{len(batch)}</b>",
                ""
            ]
            
            for reason, items in sorted(by_reason.items(), key=lambda x: -len(x[1])):
                symbols = list(set(i['symbol'] for i in items))
                avg_conf = sum(i['conf_pct'] for i in items) / len(items) if items else 0
                lines.append(f"<b>{reason}</b>: {len(items)}x")
                pretty_syms = [self._fmt_symbol(s) for s in sorted(symbols) if s]
                lines.append(f"  → Symbols: {', '.join(pretty_syms[:5])}{'...' if len(pretty_syms) > 5 else ''}")
                lines.append(f"  → Avg Conf: {avg_conf:.1f}%")
                lines.append("")
            
            msg = "\n".join(lines)
            
            import asyncio
            loop = None
            try:
                loop = asyncio.new_event_loop()
                asyncio.set_event_loop(loop)
                loop.run_until_complete(self.telegram.send_trade_alert(msg))
            finally:
                if loop:
                    try:
                        loop.close()
                    except Exception:
                        pass
        except Exception as e:
            logger.debug(f"[BLOCKED_SUMMARY] Failed to send: {e}")

    def _send_increase_telegram_alert(self, symbol: str, side: str, executed: bool, signal: dict, result: Optional[dict] = None) -> None:
        """Send a focused Telegram alert for INCREASE execution/blocks.

        CANONICAL EXEC_EVENT pattern:
          - side/positionSide always come from **submit-known** params (the `side`
            argument that this function receives), never from the exchange ack.
          - Three-state title:
              • EXECUTED      → executedQty > 0 (fill confirmed)
              • ORDER PLACED  → orderId present but executedQty == 0 (maker pending)
              • BLOCKED       → executed=False
          - Price fallback: avgPrice → limit_price → signal_price → current_price
        """
        if not self.telegram:
            return

        try:
            # Light dedupe: INCREASE can come in bursts; avoid spamming trade channel.
            # D2 fix: include orderId + fill state so PLACED→FILLED is never suppressed.
            now = time.time()
            if not hasattr(self, "_tg_increase_last_sent"):
                self._tg_increase_last_sent = {}
            _inc_oid = ""
            _inc_fstate = "B"  # BLOCK
            if executed and isinstance(result, dict):
                _inc_oid = str(result.get("orderId") or "")
                try:
                    _eq = float(result.get("executedQty", 0) or 0)
                    _ap = float(result.get("avgPrice", 0) or 0)
                except (TypeError, ValueError):
                    _eq, _ap = 0.0, 0.0
                _inc_fstate = "F" if (_eq > 0 and _ap > 0) else "P"
            key = f"{self.account_id}:{symbol}:{side}:{_inc_fstate}:{_inc_oid}"
            last = float(self._tg_increase_last_sent.get(key, 0.0) or 0.0)
            if now - last < 20.0:
                return
            self._tg_increase_last_sent[key] = now

            # ── Canonical side: always from submit-known params, never from ack ──
            # `side` arg is the positionSide we sent to Binance (LONG/SHORT).
            # This is always correct because the caller knows what it requested.
            canonical_side = str(side or "").upper()

            # ── Parse exchange ack if present ──
            ack_order_id = None
            ack_exec_qty = 0.0
            ack_avg_price = 0.0
            ack_limit_price = 0.0
            ack_liq = "UNKNOWN"
            ack_path = ""
            if isinstance(result, dict):
                ack_order_id = result.get("orderId")
                try:
                    ack_exec_qty = float(result.get("executedQty", 0) or 0)
                except (TypeError, ValueError):
                    ack_exec_qty = 0.0
                try:
                    ack_avg_price = float(result.get("avgPrice", 0) or 0)
                except (TypeError, ValueError):
                    ack_avg_price = 0.0
                try:
                    ack_limit_price = float(result.get("price", 0) or result.get("_limit_price", 0) or 0)
                except (TypeError, ValueError):
                    ack_limit_price = 0.0
                ack_liq = str(result.get("_liquidity") or "").upper() or "UNKNOWN"
                ack_path = str(result.get("_execution_path") or "")

            # ── Three-state title ──
            if not executed:
                title = "⛔ <b>INCREASE BLOCKED</b>"
            elif ack_exec_qty > 0:
                title = "✅ <b>INCREASE EXECUTED</b>"
            else:
                title = "📤 <b>INCREASE ORDER PLACED</b>"

            # ── Price fallback chain: avgPrice → limit → signal → live ──
            _disp_price = 0.0
            _price_source = ""
            if ack_avg_price > 0:
                _disp_price = ack_avg_price
                _price_source = "fill"
            elif ack_limit_price > 0:
                _disp_price = ack_limit_price
                _price_source = "limit"
            else:
                # Signal-level price
                try:
                    sp = float(signal.get("price") or signal.get("mark_price") or signal.get("mid_price") or 0)
                    if sp > 0:
                        _disp_price = sp
                        _price_source = "signal"
                except (TypeError, ValueError):
                    pass
            if _disp_price <= 0:
                try:
                    _disp_price = float(self.get_current_price(symbol) or 0)
                    _price_source = "live"
                except Exception:
                    pass

            action = str(signal.get("action_name") or signal.get("action") or "INCREASE").upper()
            conf_raw = signal.get("confidence") or signal.get("model_confidence")
            try:
                conf = float(conf_raw) if conf_raw not in (None, "") else None
            except Exception:
                conf = None
            if conf is not None and 0.0 <= conf <= 1.0:
                conf *= 100.0

            lev = signal.get("leverage") or signal.get("recommended_leverage")
            tf = signal.get("timeframe") or signal.get("tf") or ""
            sid = signal.get("_stream_id") or ""
            sig_id = signal.get("signal_id") or ""
            mu = signal.get("margin_usd")
            nu = signal.get("notional_usd")

            reason = None
            if isinstance(result, dict):
                reason = result.get("skip_reason") or result.get("reason") or result.get("detail")
            if not reason:
                reason = signal.get("reason") or signal.get("decision_reason")

            lines = [
                title,
                f"👤 <b>{self._account_label()}</b>",
                f"📊 {self._fmt_symbol_html(symbol)} | {tf}",
                f"📈 Action: <b>{action}</b> ({canonical_side})",
            ]
            if conf is not None:
                lines.append(f"🎯 Conf: {conf:.1f}%")
            if lev not in (None, ""):
                lines.append(f"⚙️ Lev: {lev}")

            # Execution/order details
            if executed and ack_order_id:
                if _disp_price > 0:
                    lines.append(f"💲 Price: <b>${_disp_price:.6f}</b> ({_price_source})")
                if ack_exec_qty > 0:
                    _disp_notional = _disp_price * ack_exec_qty
                    lines.append(f"📦 Qty: <b>{ack_exec_qty:.6f}</b>")
                    lines.append(f"💰 Notional: <b>${_disp_notional:.2f}</b>")
                else:
                    # Maker order placed but not yet filled
                    if mu not in (None, ""):
                        lines.append(f"💵 Requested margin: {mu}")
                    if nu not in (None, ""):
                        lines.append(f"📦 Requested notional: {nu}")
                lines.append(f"🏷️ Liquidity: <b>{ack_liq}</b>")
                if ack_path:
                    lines.append(f"🛤️ Path: <b>{ack_path}</b>")
                lines.append(f"🔖 OrderId: <b>{ack_order_id}</b>")
            else:
                # Blocked — show signal-level sizing
                if mu not in (None, ""):
                    lines.append(f"💵 Margin: {mu}")
                if nu not in (None, ""):
                    lines.append(f"📦 Notional: {nu}")

            if reason:
                lines.append(f"🧠 Reason: {str(reason)[:220]}")
            if sig_id or sid:
                tail = " | ".join([x for x in [f"signal_id={sig_id}" if sig_id else "", f"stream_id={sid}" if sid else ""] if x])
                if tail:
                    lines.append(f"🧾 {tail}")

            msg = "\n".join(lines)

            import asyncio
            loop = None
            try:
                loop = asyncio.new_event_loop()
                asyncio.set_event_loop(loop)
                loop.run_until_complete(self.telegram.send_trade_alert(msg))
            finally:
                if loop:
                    try:
                        loop.close()
                    except Exception:
                        pass
        except Exception as e:
            logger.debug(f"[TELEGRAM][INCREASE] send failed: {e}")

    def _maybe_send_blocked_summary(self):
        """Check if it's time to send blocked trades summary (every 30 min)."""
        now = time.time()
        if now - self._blocked_summary_last_sent >= self._blocked_summary_interval:
            if self._blocked_trades_batch:
                self._send_blocked_trades_summary()
            self._blocked_summary_last_sent = now
    
    def _log_contract(self, event: str, **fields):
        """
        Phase 0: Structured logger wrapper for profitability governance proof logs.
        Provides consistent formatting for grep-able contract events without changing existing logs.
        
        Args:
            event: Event type (e.g., 'EXECUTING SIGNAL', 'REJECTED', 'HEDGE_BYPASS_OK')
            **fields: Additional key-value pairs for structured logging
        """
        field_str = " | ".join(f"{k}={v}" for k, v in fields.items())
        log_msg = f"[{event}] | {field_str}" if field_str else f"[{event}]"
        logger.info(log_msg)
    
    def _align_margin_mode_on_startup(self):
        """
        Cross/Isolated Margin Alignment on Startup.
        
        For all traded symbols:
        - Check current margin type
        - If not CROSS, attempt to change it (when no position exists)
        - Log MARGIN_MODE_OK or MARGIN_MODE_MISMATCH
        """
        try:
            from config import SYMBOLS
            target_margin_type = os.getenv("DEFAULT_MARGIN_TYPE", "CROSS").upper()
            
            logger.info(f"[MARGIN_ALIGN] Checking margin mode for {len(SYMBOLS)} symbols (target: {target_margin_type})")
            
            aligned_count = 0
            mismatch_count = 0
            
            for symbol in SYMBOLS:
                try:
                    # Get current margin type for symbol
                    position_info = self.client.futures_position_information(symbol=symbol)
                    if not position_info:
                        continue
                    
                    current_margin = position_info[0].get('marginType', 'UNKNOWN').upper()
                    position_amt = abs(float(position_info[0].get('positionAmt', 0)))
                    
                    if current_margin == target_margin_type:
                        aligned_count += 1
                        logger.debug(f"MARGIN_MODE_OK | {symbol} | mode={current_margin}")
                    else:
                        mismatch_count += 1
                        # Try to change margin type if no position
                        if position_amt == 0:
                            try:
                                self.client.futures_change_margin_type(symbol=symbol, marginType=target_margin_type)
                                logger.info(f"MARGIN_MODE_CHANGED | {symbol} | {current_margin} -> {target_margin_type}")
                                aligned_count += 1
                                mismatch_count -= 1
                            except Exception as change_err:
                                if '-4046' in str(change_err):  # Already in target mode
                                    logger.debug(f"MARGIN_MODE_OK | {symbol} | already {target_margin_type}")
                                    aligned_count += 1
                                    mismatch_count -= 1
                                else:
                                    logger.warning(f"MARGIN_MODE_MISMATCH | {symbol} | current={current_margin} target={target_margin_type} | Cannot change: {change_err}")
                        else:
                            logger.warning(f"MARGIN_MODE_MISMATCH | {symbol} | current={current_margin} target={target_margin_type} | Cannot change with open position (amt={position_amt})")
                            
                except Exception as sym_err:
                    logger.debug(f"[MARGIN_ALIGN] Error checking {symbol}: {sym_err}")
            
            logger.info(f"[MARGIN_ALIGN] Complete: {aligned_count} aligned, {mismatch_count} mismatched")
            
        except Exception as e:
            logger.warning(f"[MARGIN_ALIGN] Startup margin alignment failed: {e}")
    
    def _cleanup_pending_messages(self, stream_key: str, group_name: str):
        """
        Clean up stale pending messages in consumer group (Task D).
        
        On startup and periodically:
        1. Check XPENDING for pending messages
        2. Auto-claim messages older than STALE_SIGNAL_SEC
        3. Acknowledge them with skip reason STALE_PENDING_DROPPED
        """
        try:
            import time
            stale_threshold_ms = int(os.getenv("STALE_SIGNAL_SEC", "300")) * 1000  # 5 minutes default
            
            # Get pending summary
            pending = self.redis.xpending(stream_key, group_name)
            if not pending or pending['pending'] == 0:
                return
            
            pending_count = pending['pending']
            logger.info(f"[PENDING_HYGIENE] {pending_count} pending messages in {group_name}")
            
            # Get detailed pending messages
            pending_detail = self.redis.xpending_range(
                stream_key, group_name, 
                min='-', max='+', count=100
            )
            
            stale_count = 0
            now_ms = int(time.time() * 1000)
            
            for msg in pending_detail:
                message_id = msg['message_id']
                idle_time_ms = msg['time_since_delivered']
                
                if idle_time_ms > stale_threshold_ms:
                    # Claim and acknowledge stale message
                    try:
                        # XCLAIM to take ownership
                        claimed = self.redis.xclaim(
                            stream_key, group_name, 
                            f"{self.account_id}:hygiene",
                            min_idle_time=stale_threshold_ms,
                            message_ids=[message_id]
                        )
                        
                        # Immediately XACK to mark as processed
                        if claimed:
                            self.redis.xack(stream_key, group_name, message_id)
                            stale_count += 1
                            
                            # Publish skip event
                            skip_event = {
                                "type": "skip",
                                "reason_code": "STALE_PENDING_DROPPED",
                                "message_id": message_id,
                                "idle_time_ms": idle_time_ms,
                                "account_id": self.account_id,
                                "ts_ms": now_ms
                            }
                            try:
                                self.redis.xadd("signals:execution:skips", skip_event, maxlen=10000)
                            except Exception:
                                pass
                                
                    except Exception as e:
                        logger.debug(f"[PENDING_HYGIENE] Failed to claim {message_id}: {e}")
            
            if stale_count > 0:
                logger.warning(f"[PENDING_HYGIENE] Dropped {stale_count} stale messages (>{stale_threshold_ms}ms idle)")
                
        except Exception as e:
            logger.debug(f"[PENDING_HYGIENE] Error during cleanup: {e}")
    
